INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_bombay-perfumery', 'bombay-perfumery', 'Bombay Perfumery', 'India', 'Mumbai', 'Artisan perfumery', 'https://www.bombayperfumery.com', 'artisan', 'A contemporary fragrance house based out of Mumbai offering progressive perfumery. Its EDPs are Indian at heart, modern in aesthetic and unique in experience; crafted by renowned international perfumers. Claims a 30-year legacy in the fragrance business. Address: 31 Manoj Industrial Estate, G D Ambekar Road, Wadala, Mumbai 400031.', 8, 0, 0, NULL, 4, 0);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_skinn-by-titan', 'skinn-by-titan', 'SKINN by Titan', 'India', NULL, 'Designer / niche perfumery', 'https://www.skinn.in', 'designer', 'Titan''s fragrance brand. Runs #NotesFromAPerfumer featuring principal perfumer Ilias Ermenidis, ''the creative genius behind SKINN Noura perfumes''. Collections: Raw, Verge, Sheer, Celeste, Nude, Steele, Pristine, Tales, Noura, Nox, Amalfi, Escapade, 247.', 25, 0, 0, NULL, 4, 0);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_neesh', 'neesh', 'NEESH', 'India', NULL, 'Designer / niche perfumery', 'https://neeshperfumes.com', 'niche', 'A haute perfumery house selling luxury Extrait De Parfum for men and women online, with 7-day easy returns. Fragrances created with perfumer Julien Rasquinet. The site''s ''Our Story'' traces its roots to 1904.', 13, 0, 0, NULL, 4, 1904);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_forest-essentials', 'forest-essentials', 'Forest Essentials', 'India', NULL, 'Designer / niche perfumery', 'https://www.forestessentialsindia.com', 'designer', 'Luxury Ayurvedic beauty brand — ''a pioneer in the beauty industry, the first brand to combine traditional Ayurvedic practices with modern aesthetics''; products handcrafted using natural ingredients sourced from India; PETA approved, Ayush/GMP/ISO certified.', 20, 0, 0, NULL, 3, 0);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_scentedelic', 'scentedelic', 'Scentedelic', 'India', NULL, 'Inspired fragrances & originals', 'https://scentedelic.com', 'indian_clone', '''SOURCED WITH INTEGRITY, CRAFTED FOR EXCELLENCE'' — small-batch perfumery where ''each ingredient is carefully macerated''; fragrances ''charged with positive energy and blessings''; cruelty-free; all scents unisex. Sells Parfum Extrait in 50ml bottles. Contact: +91-6355869747.', 7, 0, 0, NULL, 4, 0);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_heavenduft', 'heavenduft', 'Heavenduft', 'India', 'Mumbai', 'Artisan perfumery', 'https://heavenduft.in', 'artisan', '''Artisan Perfume House'' founded 23 June 2020 by independent perfumer Tausif Iqbal Shaikh. Artisan perfumes crafted with natural oils, pure attars, agarwood and sandalwood oils — original creations, not clones. Address: Sewree, Wadala, Mumbai 400031.', 11, 0, 0, NULL, 4, 2020);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_perfume-oil-corner', 'perfume-oil-corner', 'Perfume Oil Corner', 'India', NULL, 'Inspired fragrances & originals', 'https://perfumeoilcorner.in', 'indian_clone', 'Sells 30ml bottles of ''inspired by'' perfumes at a standard Rs.650. Claim on product pages: ''98.5% exact same aroma'' and ''80% concentrated perfume oils'' (brand claims, not independent findings). Also sells sample sets and ''inspired by'' attars.', 10, 0, 0, NULL, 4, 0);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_bella-vita', 'bella-vita', 'Bella Vita Luxury', 'India', NULL, 'Mass-market fragrances', 'https://bellavitaorganic.com', 'mass', 'Mass-market perfume brand (bellavitaorganic.com) — large affordable fragrance catalog: EDPs, minis, gift sets, pocket sprays. No inspired-by claims on the site; original affordable creations.', 30, 0, 0, NULL, 4, 0);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_no-name-perfume', 'no-name-perfume', 'No Name Perfume', 'India', NULL, 'Inspired fragrances & originals', 'https://nonameperfume.in/', 'indian_clone', 'Indian clone house (nonameperfume.in). 108 perfumes with explicit brand-stated inspired-by mappings (102) and house originals (6). Researched 2026-10-02.', 108, 0, 0, NULL, 4, 0);
INSERT INTO houses (id, slug, name, country, region, main_activity, website_url, house_type, description, perfume_count, earliest_year, latest_year, avg_similarity_score, trust_rating, founded_year) VALUES ('house_kannauj-fragrance', 'kannauj-fragrance', 'Kannauj Fragrance', 'India', 'Kannauj, Uttar Pradesh', 'Traditional attars & natural oils', 'https://kannaujfragrance.com/', 'attar_maker', 'Traditional Kannauj attar maker. 32 alcohol-free attars. One explicit mapping (Blue Lady → Rasasi Blue Lady). Researched 2026-10-02.', 32, 0, 0, NULL, 4, 0);
