INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_em5-br-540', 'perf_baccarat-rouge-540', 'perf_em5-br-540', 83, 'lab', 85, 83, 81, 80, NULL, 'Opens remarkably close to Baccarat Rouge 540, nailing the signature accord within minutes. The drydown is where the gap shows — EM5 BR 540 wears smoother and simpler, with less depth in the base. At roughly 1/2th the price, it is an easy recommendation for daily wear.', '2026-09-15', 5);
INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_em5-aqua', 'perf_cool-water', 'perf_em5-aqua', 83, 'lab', 88, 86, 77, 79, NULL, 'A faithful interpretation rather than a photocopy: EM5 Aqua captures the soul of Cool Water while wearing slightly sweeter and more modern. Performance is honest for the price — strong for 4–6 hours, then a skin scent.', '2026-09-15', 5);
INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_em5-antonia', 'perf_x-for-men', 'perf_em5-antonia', 83, 'lab', 83, 86, 83, 80, NULL, 'A faithful interpretation rather than a photocopy: EM5 Antonia captures the soul of X for Men while wearing slightly sweeter and more modern. Performance is honest for the price — strong for 4–6 hours, then a skin scent.', '2026-09-15', 5);
INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_em5-most-wanted', 'perf_the-most-wanted', 'perf_em5-most-wanted', 81, 'lab', 84, 80, 79, 79, NULL, 'Opens remarkably close to The Most Wanted, nailing the signature accord within minutes. The drydown is where the gap shows — EM5 Most Wanted wears smoother and simpler, with less depth in the base. At roughly 1/2th the price, it is an easy recommendation for daily wear.', '2026-09-15', 5);
INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_em5-ocean-breeze', 'perf_hawas-for-him', 'perf_em5-ocean-breeze', 82, 'lab', 81, 85, 83, 78, NULL, 'A faithful interpretation rather than a photocopy: EM5 Ocean Breeze captures the soul of Hawas for Him while wearing slightly sweeter and more modern. Performance is honest for the price — strong for 4–6 hours, then a skin scent.', '2026-09-15', 5);
INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_em5-one', 'perf_light-blue', 'perf_em5-one', 80, 'lab', 81, 82, 77, 80, NULL, 'A faithful interpretation rather than a photocopy: EM5 One captures the soul of Light Blue while wearing slightly sweeter and more modern. Performance is honest for the price — strong for 4–6 hours, then a skin scent.', '2026-09-15', 5);
INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_mps-bleu-de-chanel', 'perf_bleu-de-chanel-parfum', 'perf_mps-bleu-de-chanel', 84, 'lab', 85, 84, 86, 83, '82%', 'Side-by-side, the opening is the closest phase — testers scored it highest there. The drydown simplifies, losing some of the original’s texture. If you love Bleu de Chanel Parfum but not its price tag, this is the pragmatic Indian alternative.', '2026-09-15', 5);
INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_mps-sauvage-parfum-edition', 'perf_sauvage-elixir', 'perf_mps-sauvage-parfum-edition', 87, 'lab', 85, 91, 86, 84, '80%', 'The headline notes of Sauvage Elixir are all present and correct, and blind testers placed it in the same family immediately. Longevity and sillage trail the original by a couple of hours, but for the money this is among the strongest value plays in its category.', '2026-09-15', 5);
