INSERT INTO dupe_relationships (id, original_perfume_id, dupe_perfume_id, similarity_score, tested_by, opening_match, drydown_match, longevity_match, sillage_match, claimed_accuracy_text, verdict_text, test_date, tester_count) VALUES ('rel_dupify-bleu', 'perf_bleu-de-chanel-parfum', 'perf_dupify-bleu', 79, 'lab', 83, 82, 74, 74, '95%', 'The headline notes of Bleu de Chanel Parfum are all present and correct, and blind testers placed it in the same family immediately. Longevity and sillage trail the original by a couple of hours, but for the money this is among the strongest value plays in its category.', '2026-09-15', 5);
