INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_001', 'user_arjun_sniffs', 'perf_aventus-2', 5, 'The king, even in Delhi heat', 'Wore it to a wedding in May — 40 degrees and it still projected for 6 hours. Nothing else does that. Worth every rupee if you can stretch.', TRUE, 214);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_002', 'user_priya_scent', 'perf_aventus-2', 4, 'Great, but try the clones first', 'Beautiful smoky pineapple. That said, at this price please sample EM5 or Dupify versions before committing — you might be 85% happy for 2% of the price.', TRUE, 167);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_003', 'user_desi_nose', 'perf_sauvage-eau-de-toilette', 4, 'Office-safe beast', 'Two sprays for office, four for evenings. The ambroxan can get scratchy in peak summer afternoons — monsoon is its best season here.', TRUE, 98);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_004', 'user_priya_scent', 'perf_baccarat-rouge-540-2', 5, 'Compliment magnet, no notes', 'Strangers ask about it. That almost never happens. Saffron-amber glow that lasts all day on clothes.', TRUE, 143);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_005', 'user_fraghead_mumbai', 'perf_khamrah-2', 5, 'Viral for a reason', 'Spiced dates and praline — smells like a Goan Christmas. Lasts 10+ hours in Mumbai humidity. Best 1800 rupees in perfumery.', TRUE, 201);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_006', 'user_scentofchennai', 'perf_hawas-for-him', 5, 'Chennai summer solved', 'The only fresh scent that survives our humidity past noon. Aquatic-plum-musk, endlessly wearable.', TRUE, 132);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_007', 'user_arjun_sniffs', 'perf_em5-br-540', 4, '85% there for 2% of the price', 'Side-by-sided with the original at a meetup. Opening is shockingly close; the drydown is simpler. For 499, absurd value.', TRUE, 176);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_008', 'user_desi_nose', 'perf_em5-ocean-breeze', 4, 'Hawas on a budget', 'Fresh, clean, inoffensive — perfect gym/office scent. Lasts about 5 hours on skin, longer on clothes.', TRUE, 88);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_009', 'user_fraghead_mumbai', 'perf_mps-bleu-de-chanel', 4, 'Polished and refined', 'You can tell the oil concentration is high — it wears dense and smooth. Office-perfect. Wish the bottle was bigger than 8ml.', TRUE, 74);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_010', 'user_priya_scent', 'perf_mps-naxos-2020', 5, 'Honey-tobacco heaven', 'The best thing I have smelled under 500 rupees. Rich, warm, addictive — winter essential.', TRUE, 92);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_011', 'user_desi_nose', 'perf_dupify-aventus', 3, 'Good, not great', 'Pleasant fruity-woody scent, but the smoky birch depth of the original is missing. Fine for the price, EM5 edges it in my testing.', TRUE, 61);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_012', 'user_arjun_sniffs', 'perf_tobacco-vanille-2', 5, 'Winter royalty', 'Too heavy for Indian summer, but December-January evenings? Unbeatable. Tobacco, vanilla, dried fruit — pure luxury.', TRUE, 117);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_013', 'user_scentofchennai', 'perf_boond-maati-mitti-attar', 5, 'Petrichor in a bottle', 'Smells exactly like the first rain on dry earth. Deeply Indian, deeply moving. A drop lasts all day.', TRUE, 85);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_014', 'user_fraghead_mumbai', 'perf_arabian-aroma-ombre-leather', 4, 'Solid leather', 'Raspberry-leather done well. Not identical to the Tom Ford, but a genuinely good scent in its own right.', TRUE, 58);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_015', 'user_desi_nose', 'perf_club-de-nuit-intense-man', 4, 'The legend delivers', 'Harsh first 20 minutes, then pure Aventus-adjacent glory. Let it macerate two weeks after buying — trust me.', TRUE, 149);
INSERT INTO reviews (id, user_id, perfume_id, rating, title, body, verified_purchase, helpful_votes) VALUES ('rev_016', 'user_arjun_sniffs', 'perf_sauvage-elixir', 5, 'Sauvage, but grown up', 'Denser, spicier, more refined than the EDT. The licorice note is divisive — sample first. Performance is elite.', FALSE, 66);
INSERT INTO articles (id, slug, title, category, excerpt, body, author_name, published_at, is_published) VALUES ('art_01', 'lab-tested-5-aventus-dupes-honest-ranking', 'We lab-tested 5 Aventus dupes — here is the honest ranking', 'review', 'Five Indian alternatives to Creed Aventus, one blind panel, zero sponsorship. The winner surprised us.', '<p>Creed Aventus costs roughly ₹24,500 in India. Every Indian clone house has an answer to it — but which answers are honest? Our five-person panel wore each dupe for a full day in 38°C Delhi heat, blind, and scored opening, drydown, longevity and sillage separately.</p><p><strong>1. EM5’s interpretation (₹499)</strong> — our lab score: the highest of the batch. The smoky pineapple opening is strikingly close; only the drydown’s depth gives it away. Best value in the test by a mile.</p><p><strong>2. Armaf Club de Nuit Intense Man (₹2,200)</strong> — the legend. Harsher opening than the rest, but the drydown is the closest thing to Aventus under ₹3,000. Let it macerate two weeks.</p><p><strong>3. Dupify’s Aventus (₹599)</strong> — pleasant and fruity, but the birch smoke that defines Aventus is muted. A good scent; a less convincing clone.</p><p><strong>4. Purenso’s Aventus oil (₹245)</strong> — remember this is an oil, not a spray. Intimate, long-lasting on skin, but it never projects like the original.</p><p><strong>5. Celestial’s Aventus Noir (₹749)</strong> — community-suggested; our lab has not completed full testing yet. Early impressions are positive but unverified.</p><p>The takeaway: you can get 80%+ of the Aventus experience for under ₹1,000 in India today. That is exactly why Scentiqa exists.</p>', 'Scentiqa Lab', '2026-09-20', TRUE);
INSERT INTO articles (id, slug, title, category, excerpt, body, author_name, published_at, is_published) VALUES ('art_02', 'house-of-em5-499-phenomenon', 'House of EM5: decoding the ₹499 phenomenon', 'column', 'How a Mumbai clone house became India’s gateway drug to niche perfumery.', '<p>Walk into any Indian fragrance community and ask where beginners should start. The answer, overwhelmingly, is three letters: EM5.</p><p>House of EM5’s playbook is disarmingly simple — take the world’s most-cloned scents (Baccarat Rouge 540, Cool Water, Hawas), bottle competent interpretations as 50ml EDPs, and sell them on Flipkart and Amazon for around ₹499. No mystique, no attar-shop theatrics.</p><p>Our lab testing puts their BR540 interpretation among the strongest value scores we have measured. The Hawas-inspired Ocean Breeze is arguably the best ₹499 fresh scent in the country for Indian summers.</p><p>Are they identical to the originals? No — and our claimed-vs-lab panels show exactly where the gaps are. But EM5 has done something the luxury houses never bothered to: make great-smelling perfumery accessible to a college student in Indore. That deserves respect.</p>', 'Scentiqa Editorial', '2026-09-12', TRUE);
INSERT INTO articles (id, slug, title, category, excerpt, body, author_name, published_at, is_published) VALUES ('art_03', 'spot-fake-creed-aventus-india', 'How to spot a fake Creed Aventus in India (2026 guide)', 'guide', 'Grey-market Aventus floods Indian marketplaces. Here is how to protect yourself.', '<p>Aventus is the most counterfeited niche perfume in India. If a deal looks too good — ₹8,000 for a 100ml “sealed” bottle — it is fake. Full stop.</p><p><strong>Checklist:</strong></p><p>1. <strong>Batch code:</strong> etched on the back of the bottle, matching the box. No sticker-only codes.<br/>2. <strong>Atomizer:</strong> genuine Creed atomizers are precise and quiet; fakes sputter.<br/>3. <strong>Juice color:</strong> Aventus varies by batch, but neon or murky juice is a red flag.<br/>4. <strong>Seller:</strong> buy only from sellers on our verified list. Marketplace listings with stock photos and no GST invoice are the danger zone.</p><p>When in doubt, post photos in our <a href="/forum/fakes-help-desk">Fakes Help Desk</a> — the community authenticates dozens of bottles a week.</p><p>And remember: a great Indian dupe at ₹499 beats a fake “Aventus” at ₹8,000 every single time.</p>', 'Scentiqa Trust Team', '2026-09-05', TRUE);
INSERT INTO articles (id, slug, title, category, excerpt, body, author_name, published_at, is_published) VALUES ('art_04', 'arabian-aroma-seduction-bestseller', 'Arabian Aroma’s original “Seduction” overtakes its dupes', 'launch', 'The Kanpur house’s original creation is now its bestseller — a sign of India’s maturing clone market.', '<p>Something interesting is happening in Kanpur. Arabian Aroma — the house that reportedly moved ~500,000 bottles in 2024 largely on inspired fragrances — says its original creation, Seduction, is now its bestselling scent.</p><p>It is a milestone worth noting. India’s clone houses began as pure alternatives to Western luxury; now the best of them are developing original identities. Seduction’s fruity-woody profile has earned a 4.5 community rating on Scentiqa, higher than most of the house’s inspired line.</p><p>The arc of every mature dupe market — from the Middle East to now India — bends from imitation to creation. We will be watching.</p>', 'Scentiqa Newsroom', '2026-08-28', TRUE);
INSERT INTO articles (id, slug, title, category, excerpt, body, author_name, published_at, is_published) VALUES ('art_05', 'readers-choice-awards-2026-voting-opens', 'Scentiqa Readers’ Choice Awards 2026 — voting is open', 'awards', 'Best Dupe House, Best Summer Beast, Best Attar, Best Value Buy. Your vote decides.', '<p>Voting is now open for the first Scentiqa Readers’ Choice Awards, celebrating the scents and houses India actually wears.</p><p><strong>Categories:</strong> Best Dupe House of 2026, Best Summer Beast, Best Attar, and Best Value Buy under ₹1,000.</p><p>One vote per member per category. Voting closes 31 October 2026, and winners are announced in the first week of November. <a href="/awards/2026">Cast your vote here</a>.</p>', 'Scentiqa Editorial', '2026-09-25', TRUE);
INSERT INTO forum_categories (id, slug, name, description, sort_order) VALUES ('fcat_beginners', 'beginners', 'Beginners’ Corner', 'New to fragrance? Start here — no question is too basic.', 0);
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_beginners_1', 'fcat_beginners', 'user_desi_nose', 'How many sprays is too many in Indian summer?', FALSE, FALSE, 2);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_beginners_1_1', 'ftop_beginners_1', 'user_desi_nose', 'I do 4 sprays of Hawas and my colleagues say it’s strong. What’s the rule for 40-degree heat?');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_beginners_1_2', 'ftop_beginners_1', 'user_arjun_sniffs', 'Heat amplifies projection. Rule of thumb: halve your winter sprays in May-June. 2-3 sprays max for fresh scents, 1-2 for heavy orientals.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_beginners_1_3', 'ftop_beginners_1', 'user_priya_scent', 'Also: spray clothes, not just skin. It lasts longer and projects less aggressively in humidity.');
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_beginners_2', 'fcat_beginners', 'user_fraghead_mumbai', 'First niche purchase — Aventus or BR540?', FALSE, FALSE, 2);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_beginners_2_1', 'ftop_beginners_2', 'user_fraghead_mumbai', 'Saved up 25k. Should I buy Aventus or BR540? I live in Mumbai.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_beginners_2_2', 'ftop_beginners_2', 'user_priya_scent', 'Mumbai humidity + BR540 = you will smell amazing but you might suffocate others in locals. Aventus wears better in heat.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_beginners_2_3', 'ftop_beginners_2', 'user_arjun_sniffs', 'Honestly? Buy neither first. Spend 2k on EM5 BR540 + Armaf CDNIM + Hawas, live with the DNAs for a month, then decide.');
INSERT INTO forum_categories (id, slug, name, description, sort_order) VALUES ('fcat_dupe-talk', 'dupe-talk', 'Dupe Talk', 'Indian alternatives, clone houses, similarity debates.', 0);
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_dupe-talk_1', 'fcat_dupe-talk', 'user_desi_nose', 'EM5 vs Dupify Aventus — final verdict?', FALSE, FALSE, 2);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_dupe-talk_1_1', 'ftop_dupe-talk_1', 'user_desi_nose', 'Both claim to be the Aventus killer. Who wins?');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_dupe-talk_1_2', 'ftop_dupe-talk_1', 'user_arjun_sniffs', 'Our lab scored EM5 higher on drydown match. Dupify’s opening is nice but fades faster. Full breakdown in the lab report article.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_dupe-talk_1_3', 'ftop_dupe-talk_1', 'user_fraghead_mumbai', 'EM5 for me too. Also Dupify’s “95%” claim vs our lab’s number — always check the claimed-vs-lab panel.');
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_dupe-talk_2', 'fcat_dupe-talk', 'user_priya_scent', 'My Perfume Secrets accuracy claims — legit?', FALSE, FALSE, 1);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_dupe-talk_2_1', 'ftop_dupe-talk_2', 'user_priya_scent', 'MPS prints “82% accuracy” on the Bleu listing. How is that measured?');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_dupe-talk_2_2', 'ftop_dupe-talk_2', 'user_arjun_sniffs', 'It’s the house’s own claim — marketing, basically. Our lab independently scored it in the low 80s, so this one happens to be fair. Not all are.');
INSERT INTO forum_categories (id, slug, name, description, sort_order) VALUES ('fcat_attars', 'attars', 'Attars & Kannauj', 'Traditional Indian perfumery — attars, ruhs, shamamas.', 0);
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_attars_1', 'fcat_attars', 'user_scentofchennai', 'Mitti attar recommendations for a beginner?', FALSE, FALSE, 2);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_attars_1_1', 'ftop_attars_1', 'user_scentofchennai', 'I want to try the famous petrichor attar. Boond? Sugandhco?');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_attars_1_2', 'ftop_attars_1', 'user_arjun_sniffs', 'Boond’s Maati is the crowd favourite and easy to find on Amazon. Apply one drop — attars are concentrated.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_attars_1_3', 'ftop_attars_1', 'user_desi_nose', 'Second Boond. Also try their Ruh Gulab if you like florals.');
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_attars_2', 'fcat_attars', 'user_fraghead_mumbai', 'How do you wear attar without overdoing it?', FALSE, FALSE, 1);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_attars_2_1', 'ftop_attars_2', 'user_fraghead_mumbai', 'One drop of shamama filled my whole office. Help.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_attars_2_2', 'ftop_attars_2', 'user_priya_scent', 'Behind the ears and a touch on the wrists. Never more than two drops for potent ones like shamama or oudh.');
INSERT INTO forum_categories (id, slug, name, description, sort_order) VALUES ('fcat_fakes-help-desk', 'fakes-help-desk', 'Fakes Help Desk', 'Suspect a counterfeit? Post photos, get community authentication.', 0);
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_fakes-help-desk_1', 'fcat_fakes-help-desk', 'user_fraghead_mumbai', 'Is this Aventus batch code legit? (photos inside)', FALSE, FALSE, 1);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_fakes-help-desk_1_1', 'ftop_fakes-help-desk_1', 'user_fraghead_mumbai', 'Bought from a marketplace seller for 12k. Batch code looks etched but the atomizer sputters.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_fakes-help-desk_1_2', 'ftop_fakes-help-desk_1', 'user_arjun_sniffs', 'Sputtering atomizer + that price = red flags. Post a photo of the batch code next to the box code — they must match exactly.');
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_fakes-help-desk_2', 'fcat_fakes-help-desk', 'user_desi_nose', '“Sealed” Sauvage for 4000 — fake?', FALSE, FALSE, 1);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_fakes-help-desk_2_1', 'ftop_fakes-help-desk_2', 'user_desi_nose', 'Seller claims sealed tester. 4000 for 100ml.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_fakes-help-desk_2_2', 'ftop_fakes-help-desk_2', 'user_priya_scent', 'Fake. Authentic Sauvage 100ml never sells that low in India. Buy from our verified sellers list instead.');
INSERT INTO forum_categories (id, slug, name, description, sort_order) VALUES ('fcat_general', 'general', 'General Discussion', 'Everything fragrance that doesn’t fit elsewhere.', 0);
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_general_1', 'fcat_general', 'user_arjun_sniffs', 'What did you wear today? (daily thread)', FALSE, FALSE, 2);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_general_1_1', 'ftop_general_1', 'user_arjun_sniffs', 'Naxos. It’s October, finally cool enough.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_general_1_2', 'ftop_general_1', 'user_priya_scent', 'MPS Naxos 2020 — the dupe, and honestly I’m not mad about it.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_general_1_3', 'ftop_general_1', 'user_scentofchennai', 'Hawas. Chennai doesn’t do October.');
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_general_2', 'fcat_general', 'user_priya_scent', 'Monsoon fragrance rotation', FALSE, FALSE, 1);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_general_2_1', 'ftop_general_2', 'user_priya_scent', 'What survives Mumbai monsoon? My fresh scents die in 2 hours.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_general_2_2', 'ftop_general_2', 'user_desi_nose', 'Ambroxan-heavy scents (Sauvage DNA) cut through humidity. Also: attars. Oils don’t wash out like alcohol sprays.');
INSERT INTO forum_categories (id, slug, name, description, sort_order) VALUES ('fcat_niche', 'niche', 'Niche & Luxury', 'Creed, Amouage, Xerjoff and beyond.', 0);
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_niche_1', 'fcat_niche', 'user_arjun_sniffs', 'Interlude Man in Indian summer — madness?', FALSE, FALSE, 1);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_niche_1_1', 'ftop_niche_1', 'user_arjun_sniffs', 'One spray of Interlude in May cleared a room. Respect the beast.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_niche_1_2', 'ftop_niche_1', 'user_priya_scent', 'It’s a November-to-February scent in India. Full stop.');
INSERT INTO forum_topics (id, category_id, user_id, title, is_pinned, is_locked, reply_count) VALUES ('ftop_niche_2', 'fcat_niche', 'user_fraghead_mumbai', 'Is Xerjoff worth 3x Parfums de Marly?', FALSE, FALSE, 1);
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_niche_2_1', 'ftop_niche_2', 'user_fraghead_mumbai', 'Naxos vs Layton — both sweet, very different prices.');
INSERT INTO forum_posts (id, topic_id, user_id, body) VALUES ('fpost_niche_2_2', 'ftop_niche_2', 'user_arjun_sniffs', 'Different beasts. Naxos is honey-tobacco opulence; Layton is apple-lavender elegance. Try both via MPS/Naxos clones first for under 500.');
